import { tags } from "typia";

/**
 * Payment-related metrics portion of the shoppingMall system overview
 * dashboard.
 *
 * This section consolidates high-level payment method performance and
 * reliability indicators based on snapshot tables such as
 * `shopping_mall_payment_method_stats` and related aggregates. It helps admins
 * quickly detect anomalies in payment success rates or shifts in method usage.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallSystemOverviewPaymentsSection = {
  /**
   * Total count of logical payment attempts recorded during the reporting
   * window, across all payment methods.
   */
  totalPayments: number & tags.Type<"int32">;

  /**
   * Number of payments that completed successfully during the reporting
   * window.
   */
  successfulPayments: number & tags.Type<"int32">;

  /**
   * Number of payments that failed or were declined during the reporting
   * window.
   */
  failedPayments: number & tags.Type<"int32">;

  /**
   * Overall payment success rate for the reporting window expressed as a
   * fraction between 0 and 1.
   *
   * Typically computed as `successfulPayments / max(totalPayments, 1)`.
   */
  paymentSuccessRate: number;
};
